    int colIndex = Character.toUpperCase(col) - 'A' + 1;
    Pipe frontPipe = getPipeQueue() == null ? null : getPipeQueue().peek();
    if (frontPipe == null || getMap() == null || getCellStack() == null)
    {
      return false;
    }
    if (getMap().placePipe(frontPipe, row, colIndex))
    {
      FillableCell placedCell = getMap().getFillableCell(row, colIndex);
      if (placedCell != null)
      {
        getCellStack().push(placedCell);
      }
      getPipeQueue().poll();
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    }
    return false;
    
